using System;using UnityEngine;
namespace LWS.TruckSports {
// Reuses the established actual-mesh wreck presentation with a sport-neutral truck owner.
// Child transforms retain every piece pose in SportsMotionReplay; scale-zero hides dormant parts.
public sealed class SportsFragmentRig:MonoBehaviour {
 [Serializable]public sealed class Piece{public Transform source;public Rigidbody body;public Collider collider;public Renderer renderer;}
 public SportsEventTruck truck;public Rigidbody sourceBody;public Renderer[] sourceRenderers;public SportsTruckAppearanceHost appearanceHost;public SportsTruckFragmentPresentation fragmentPresentation;bool[] rendererStates;Rigidbody OwnerBody=>sourceBody!=null?sourceBody:truck.body;public Piece[] pieces;public bool Bursting{get;private set;}Vector3 visualScale;MaterialPropertyBlock tint;
 void Awake(){if(truck!=null)visualScale=truck.visuals.localScale;if(sourceRenderers!=null){rendererStates=new bool[sourceRenderers.Length];for(int i=0;i<rendererStates.Length;i++)rendererStates[i]=sourceRenderers[i].enabled;}tint=new MaterialPropertyBlock();var own=OwnerBody.GetComponentsInChildren<Collider>(true);foreach(var p in pieces)foreach(var c in own)if(p.collider!=c)Physics.IgnoreCollision(p.collider,c,true);}
 public void ResetBody(){if(tint==null)Awake();Bursting=false;if(truck!=null)truck.visuals.localScale=visualScale;if(sourceRenderers!=null)for(int i=0;i<sourceRenderers.Length;i++)sourceRenderers[i].enabled=rendererStates[i];foreach(var p in pieces){p.body.isKinematic=true;p.collider.enabled=false;p.renderer.GetComponent<MeshFilter>().sharedMesh=p.source.GetComponent<MeshFilter>().sharedMesh;p.body.transform.localScale=Vector3.zero;}appearanceHost?.ReassertIntactPresentation();fragmentPresentation?.ResetPresentation(); }
 public void Burst(){if(Bursting)return;Bursting=true;bool customRendering=fragmentPresentation!=null&&fragmentPresentation.BeforeBurst();if(fragmentPresentation!=null&&!customRendering)appearanceHost?.UseOriginalForUnavailableFragments();foreach(var p in pieces){var filter=p.source.GetComponent<MeshFilter>();p.renderer.GetComponent<MeshFilter>().sharedMesh=filter.sharedMesh;p.body.transform.SetPositionAndRotation(p.source.position,p.source.rotation);var scale=p.source.lossyScale;var parent=p.body.transform.parent.lossyScale;p.body.transform.localScale=new Vector3(scale.x/parent.x,scale.y/parent.y,scale.z/parent.z);p.source.GetComponent<Renderer>().GetPropertyBlock(tint);p.renderer.SetPropertyBlock(tint);p.collider.enabled=true;p.body.isKinematic=false;var direction=p.source.TransformPoint(filter.sharedMesh.bounds.center)-OwnerBody.worldCenterOfMass;if(direction.sqrMagnitude<.01f)direction=Vector3.up;direction.Normalize();p.body.linearVelocity=Vector3.ClampMagnitude(OwnerBody.GetPointVelocity(p.source.position),30)+direction*4+Vector3.up*4;p.body.angularVelocity=Vector3.ClampMagnitude(OwnerBody.angularVelocity,10)+new Vector3(4,6,3);p.body.WakeUp();}if(truck!=null)truck.Power(false);OwnerBody.isKinematic=true;OwnerBody.detectCollisions=false;if(truck!=null)truck.visuals.localScale=Vector3.zero;if(sourceRenderers!=null)foreach(var renderer in sourceRenderers)renderer.enabled=false;if(customRendering)fragmentPresentation.AfterBurst();}
 public void Freeze(){if(pieces!=null)foreach(var p in pieces)if(p.body!=null){p.body.isKinematic=true;p.collider.enabled=false;}}
 void OnDisable(){Freeze();}
}}
